custom_qss:
/* ============================================================
   ANOMALY — the Abstract one. Super-unique: tiled banding +
   double-border frames + huge letter-spacing + INVERTED selection.
   One amber-ink palette on near-black. Deliberately off.
   ============================================================ */

* { color: #e8dcc0; letter-spacing: 1px; }
QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent; border: none;
}

/* window: tiled diagonal stripe field */
QMainWindow { background: qlineargradient(x1:0, y1:0, x2:0.25, y2:0.25, spread:repeat, stop:0 #1a140c, stop:1 #0d0b08) !important; border: none; }
QDialog {
    background: #0d0b08 !important;
    border: 3px solid #2e2618;        /* double-border: thick outer */
}

/* menubar: flat, oversized tracking, dim selected (inverted) */
QMenuBar { background: #100d09 !important; border: none; border-bottom: 1px solid #2e2618; }
QMenuBar::item { padding: 5px 14px; background: transparent !important; color: #7a6c4e; letter-spacing: 3px; }
QMenuBar::item:selected { background: #100d09 !important; color: #7a6c4e; border-bottom: 2px solid #e0a940; }
QMenuBar::item:disabled { color: #4a4230; }

/* popup menus: double-framed, striped selected (inverted = dim) */
QMenu {
    background: #14110c !important;
    border: 3px solid #2e2618; padding: 6px; font-size: 12px;}
QMenu::item { padding: 7px 26px 7px 14px; background: transparent !important; color: #e8dcc0; letter-spacing: 2px; }
QMenu::item:selected { background: #0d0b08 !important; color: #7a6c4e; border-left: 3px solid #e0a940; }
QMenu::item:disabled { color: #4a4230; }
QMenu::separator { height: 2px; background: #2e2618; margin: 6px 10px; }

/* toolbar: flat, oversized tracking, inverted active (dim) */
QToolBar { background: #100d09 !important; border: none; border-bottom: 1px solid #2e2618; spacing: 3px; padding: 4px; }
QToolBar::separator { background: #2e2618; width: 1px; margin: 6px 5px; }
QToolBar QToolButton, QToolButton { background: transparent !important; padding: 6px 12px; border: 1px solid transparent; color: #b8a880; letter-spacing: 2px; font-size: 12px;}
QToolBar QToolButton:hover, QToolButton:hover { background: #1f1a12 !important; border: 1px solid #4a3d24; color: #e0a940; }
QToolBar QToolButton:checked, QToolBar QToolButton:pressed,
QToolButton:checked, QToolButton:pressed { background: #0d0b08 !important; border: 1px solid #e0a940; color: #7a6c4e; }

/* buttons: double-border cards, amber on hover, inverted checked (dim) */
QPushButton {
    background: #14110c !important;
    border: 2px solid #2e2618; border-radius: 2px; padding: 8px 22px;
    color: #e8dcc0; font-weight: 600; letter-spacing: 3px; font-size: 12px;}
QPushButton:hover { background: #1f1a12 !important; border: 2px solid #e0a940; color: #e0a940; }
QPushButton:pressed { background: #e0a940 !important; color: #0d0b08; }
QPushButton:checked { background: #0d0b08 !important; border: 2px solid #e0a940; color: #7a6c4e; }
QPushButton:default { border: 2px solid #e0a940; }
QPushButton:disabled { background: #100d09 !important; color: #4a4230; border: 2px solid #2e2618; }

/* inputs: double-border wells */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background: #080705 !important;
    border: 2px solid #2e2618; border-radius: 2px; padding: 7px 12px;
    color: #e0a940; letter-spacing: 2px;
    selection-background-color: #e0a940; selection-color: #0d0b08; font-size: 12px;}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus { border: 2px solid #e0a940; }
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled, QTextEdit:disabled, QPlainTextEdit:disabled { color: #4a4230; }
QSpinBox::up-button, QSpinBox::down-button, QDoubleSpinBox::up-button, QDoubleSpinBox::down-button { background: transparent !important; border: none; width: 16px; }

QComboBox { background: #080705 !important; border: 2px solid #2e2618; border-radius: 2px; padding: 7px 12px; color: #e8dcc0; letter-spacing: 2px; font-size: 12px;}
QComboBox:hover { border: 2px solid #4a3d24; }
QComboBox:focus { border: 2px solid #e0a940; }
QComboBox::drop-down { border: none; background: transparent !important; width: 18px; }
QComboBox QAbstractItemView { background: #14110c !important; border: 2px solid #2e2618; padding: 5px; selection-background-color: #0d0b08; selection-color: #7a6c4e; font-size: 12px;}

QCheckBox, QRadioButton { color: #e8dcc0; background: transparent !important; padding: 3px; letter-spacing: 2px; }
QCheckBox::indicator, QRadioButton::indicator { width: 16px; height: 16px; border-radius: 2px; background: #080705 !important; border: 2px solid #4a3d24; }
QRadioButton::indicator { border-radius: 8px; }
QCheckBox::indicator:hover, QRadioButton::indicator:hover { border: 2px solid #e0a940; }
QCheckBox::indicator:checked, QRadioButton::indicator:checked { background: #e0a940 !important; border: 2px solid #e0a940; }

QTabBar::tab { background: transparent !important; color: #7a6c4e; padding: 9px 18px; border: 1px solid transparent; border-bottom: 2px solid transparent; letter-spacing: 3px; }
QTabBar::tab:hover { color: #e8dcc0; }
QTabBar::tab:selected { color: #7a6c4e; border: 1px solid #e0a940; border-bottom: 2px solid #e0a940; }
QTabWidget::pane { border: none; border-top: 2px solid #2e2618; }

/* docks: tiled stripe + double frame */
QDockWidget { background: qlineargradient(x1:0, y1:0, x2:0.25, y2:0.25, spread:repeat, stop:0 #17130d, stop:1 #100d09) !important; border: 2px solid #2e2618; border-radius: 2px; }
QDockWidget::title {
    background: #100d09 !important;
    border: none; border-bottom: 2px solid #2e2618; border-left: 4px solid #e0a940;
    padding: 7px 12px; color: #b8a880; font-weight: 700; letter-spacing: 2px;
}
QDockWidget::close-button, QDockWidget::float-button { background: transparent !important; border: 1px solid transparent; border-radius: 2px; padding: 3px; icon-size: 18px; }
QDockWidget::close-button:hover, QDockWidget::float-button:hover { background: #1f1a12 !important; }

QGroupBox { background: transparent !important; border: 2px solid #2e2618; border-radius: 2px; margin-top: 13px; padding-top: 11px; }
QGroupBox::title { subcontrol-origin: margin; subcontrol-position: top left; padding: 0 10px; color: #e0a940; font-weight: 700; letter-spacing: 2px; background: #0d0b08; }

/* item views: INVERTED selection — active row is DIM, others bright */
QAbstractItemView {
    background: #080705 !important; border: 2px solid #2e2618; border-radius: 2px;
    outline: none; alternate-background-color: #100d09;
    selection-background-color: #0d0b08; selection-color: #7a6c4e;
}
QAbstractItemView::item { padding: 6px 12px; border: none; border-left: 3px solid transparent; color: #e8dcc0; letter-spacing: 1px; }
QAbstractItemView::item:hover { background: #1f1a12 !important; color: #e0a940; }
QAbstractItemView::item:selected { background: #0d0b08 !important; color: #7a6c4e; border-left: 3px solid #e0a940; }
QTreeView::branch { background: transparent !important; }
QHeaderView::section { background: #100d09 !important; border: none; border-bottom: 2px solid #2e2618; padding: 7px 12px; color: #b8a880; font-weight: 700; letter-spacing: 3px; }

QScrollBar:vertical { background: #080705; width: 11px; margin: 0; border: none; }
QScrollBar::handle:vertical { background: #4a3d24; border-radius: 2px; min-height: 32px; }
QScrollBar::handle:vertical:hover { background: #e0a940; }
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical { height: 0; border: none; background: none; }
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical { background: none; }
QScrollBar:horizontal { background: #080705; height: 11px; margin: 0; border: none; }
QScrollBar::handle:horizontal { background: #4a3d24; border-radius: 2px; min-width: 32px; }
QScrollBar::handle:horizontal:hover { background: #e0a940; }
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal { width: 0; border: none; background: none; }
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal { background: none; }
QScrollBar::corner { background: none; }

QSlider::groove:horizontal { background: #080705; border: 2px solid #2e2618; height: 8px; border-radius: 2px; }
QSlider::sub-page:horizontal { background: #e0a940; border-radius: 2px; }
QSlider::add-page:horizontal { background: #080705; border-radius: 2px; }
QSlider::handle:horizontal { background: #e0a940; width: 14px; height: 16px; margin: -6px 0; border: 2px solid #0d0b08; border-radius: 2px; }
QSlider::handle:horizontal:hover { background: #f5d07a; }
QSlider::groove:vertical { background: #080705; border: 2px solid #2e2618; width: 8px; border-radius: 2px; }
QSlider::sub-page:vertical { background: #e0a940; border-radius: 2px; }
QSlider::handle:vertical { background: #e0a940; width: 16px; height: 14px; margin: 0 -6px; border: 2px solid #0d0b08; border-radius: 2px; }

QProgressBar { background: #080705; border: 2px solid #2e2618; border-radius: 2px; text-align: center; color: #b8a880; font-size: 11px; letter-spacing: 3px; min-height: 16px; }
QProgressBar::chunk { background: #e0a940; border-radius: 2px; }

QStatusBar { background: #100d09 !important; border-top: 2px solid #2e2618; color: #7a6c4e; font-size: 11px; letter-spacing: 2px; }
QStatusBar::item { border: none; }
QToolTip { background: #14110c !important; border: 2px solid #e0a940; border-radius: 2px; padding: 6px 12px; color: #e8dcc0; }
QSplitter::handle { background: #2e2618; }
QSplitter::handle:hover { background: #e0a940; }
QListView, QListWidget, QTreeWidget, QTableWidget { background: #080705 !important; border: 2px solid #2e2618; border-radius: 2px; outline: none; }
